import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Testing Policy","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/testing.md","filePath":"develop/testing.md","lastUpdated":null}'),o={name:"develop/testing.md"};function n(l,e,r,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/testing.md" target="_blank" rel="noreferrer"><code>.agents/testing.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="testing-policy" tabindex="-1">Testing Policy <a class="header-anchor" href="#testing-policy" aria-label="Permalink to &quot;Testing Policy&quot;">​</a></h1><p>This document is the authoritative testing policy for contributors and AI agents in this repository.</p><h2 id="core-policy" tabindex="-1">Core Policy <a class="header-anchor" href="#core-policy" aria-label="Permalink to &quot;Core Policy&quot;">​</a></h2><ul><li>Treat tests as part of normal validation when code changes affect behavior, contracts, bug fixes, or existing tested surfaces.</li><li>Add or update focused tests for new behavior, changed behavior, shared contracts, and regression-prone bug fixes when the package or app has a practical test surface.</li><li>Keep test work proportional to risk. Do not create broad, brittle, or low-signal tests for markdown-only edits, copy-only tweaks, purely mechanical formatting, or changes with no runtime behavior.</li><li>Run the narrowest relevant test command after implementation and after the fix command from <a href="/SaaSWeave/develop/workflow">Workflow</a>.</li><li>Use unit tests for domain logic, contracts, utilities, and component behavior that can be tested locally.</li><li>Use e2e tests for browser workflows, auth/routing behavior, and integration paths that unit tests cannot cover.</li><li>Inspect nearby tests before generating new ones.</li><li>Use Vite+ testing conventions, not standalone Vitest defaults.</li></ul><h2 id="test-commands" tabindex="-1">Test Commands <a class="header-anchor" href="#test-commands" aria-label="Permalink to &quot;Test Commands&quot;">​</a></h2><p>Canonical commands:</p><ul><li><code>vp run test:unit:run</code></li><li><code>vp run test:e2e:run</code></li></ul><p>Prefer package-local test commands when they exist and cover the touched surface. Use the repo wrappers when changes span packages or when package-local coverage is not available.</p><h2 id="coverage-gates" tabindex="-1">Coverage Gates <a class="header-anchor" href="#coverage-gates" aria-label="Permalink to &quot;Coverage Gates&quot;">​</a></h2><p>CI runs <code>vp run coverage:gate</code> with risk-based per-package line floors. <code>@saasweave/jobs</code>, <code>@saasweave/worker</code>, and <code>@saasweave/observability</code> each have a blocking <strong>90% line coverage</strong> floor.</p><ul><li>Do not lower a floor to land a change.</li><li>Do not add coverage exclusions for reachable handwritten code.</li><li>For jobs and workers, cover processor routing, unsupported job names, retries, lifecycle cleanup, readiness degradation, schedules, and provider/Redis failures.</li><li>For observability, cover metric mutation, label normalization, exposition responses, and timer start/stop behavior.</li><li>Run package coverage with <code>vp test --coverage --run</code>; use <code>vp run coverage:gate</code> from the workspace when changing gate configuration or shared runtime behavior.</li></ul><h2 id="test-locations" tabindex="-1">Test Locations <a class="header-anchor" href="#test-locations" aria-label="Permalink to &quot;Test Locations&quot;">​</a></h2><p>Unit tests:</p><ul><li><code>src/**/__tests__/*.test.ts</code></li></ul><p>End-to-end tests:</p><ul><li><code>__e2e__/**/*.spec.ts</code></li></ul><p>Use <code>__e2e__</code> as the project convention for end-to-end tests.</p><h2 id="vite-vitest-setup-rule" tabindex="-1">Vite+ / Vitest Setup Rule <a class="header-anchor" href="#vite-vitest-setup-rule" aria-label="Permalink to &quot;Vite+ / Vitest Setup Rule&quot;">​</a></h2><p>When adding tests to a package or app that does not already have Vite+ testing configured:</p><ol><li>Install and configure Vite+.</li><li>Add a root <code>vite.config.ts</code> in the package or app being tested.</li><li>Do not create <code>vitest.config.ts</code>.</li><li>Put Vitest config inside <code>vite.config.ts</code> using Vite+ conventions.</li></ol><p>Default config:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vite-plus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  test: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    include: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/__tests__/**/*.test.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Explicit rules:</p><ul><li>The Vitest config belongs in <code>vite.config.ts</code>.</li><li><code>vitest.config.ts</code> should not be used in this repository.</li><li>Follow the Vite+ test docs as the source of truth: <a href="https://viteplus.dev/guide/test" target="_blank" rel="noreferrer">https://viteplus.dev/guide/test</a></li></ul><h2 id="test-design" tabindex="-1">Test Design <a class="header-anchor" href="#test-design" aria-label="Permalink to &quot;Test Design&quot;">​</a></h2><p>Generate behavior-driven tests that prioritize:</p><ul><li>happy paths</li><li>edge cases and fallback precedence</li><li>pathological inputs</li><li>regression-prone cases</li><li>contract invariants</li></ul><p>Prefer:</p><ul><li>table-driven tests</li><li>testing public contracts over internals</li><li>fixtures and builders to reduce duplication</li><li>adding regression tests for bug fixes</li><li>mirroring nearby test structure</li></ul>`,30)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
